window.GO_PROVERBS_BUNDLE = {"key":"proverbs","label":"围棋棋谚","source":"multiple — see PROVERBS.md","retrieved":"2026-11-21","license":"Mixed: Wikipedia text CC BY-SA 4.0; 《棋经十三篇》 public domain; Sensei's Library, Baidu Baike and Sohu pages are all rights reserved — personal reference use only.","counts_by_category":{"十诀":10,"新十诀":5,"布局":19,"攻防":22,"死活":4,"棋形与手筋":17,"棋理":20},"counts_by_source":{"zh.wikipedia 围棋十诀":15,"zh.wikipedia 金角银边铜肚皮":1,"baike 围棋谚语":39,"sohu 经典围棋口诀":3,"维基文库 棋经十三篇":23,"sohu 18条围棋谚语详解":6,"Sensei's Library 中文棋谚":10},"count":97,"stamp":"a6a0890e-97","proverbs":[{"id":1,"category":"十诀","order":1,"simplified":"不得贪胜","traditional":"不得貪勝","pinyin":"bù dé tān shèng","pinyin_plain":"bu de tan sheng","english":"Do not be greedy for victory.","explanation_zh":"赢一目也是赢，赢百目也是赢；优势时若贪求更多，反而会给对手可乘之机。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":"濑越宪作又作「贪不得胜」。"},{"id":2,"category":"十诀","order":2,"simplified":"入界宜缓","traditional":"入界宜緩","pinyin":"rù jiè yí huǎn","pinyin_plain":"ru jie yi huan","english":"Enter the opponent's sphere slowly.","explanation_zh":"打入或侵消对方模样时要徐徐图之，不可躁进，以免被一网打尽。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":3,"category":"十诀","order":3,"simplified":"攻彼顾我","traditional":"攻彼顧我","pinyin":"gōng bǐ gù wǒ","pinyin_plain":"gong bi gu wo","english":"When attacking, look after yourself.","explanation_zh":"攻击对方之前先顾自身安全与全局配合，自己破绽百出则攻不成立。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":4,"category":"十诀","order":4,"simplified":"弃子争先","traditional":"棄子爭先","pinyin":"qì zǐ zhēng xiān","pinyin_plain":"qi zi zheng xian","english":"Sacrifice stones to seize the initiative.","explanation_zh":"舍弃眼前小利以换取先手和主动权；争先是局部服从全局。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":5,"category":"十诀","order":5,"simplified":"舍小就大","traditional":"捨小就大","pinyin":"shè xiǎo jiù dà","pinyin_plain":"she xiao jiu da","english":"Let go the small and take the big.","explanation_zh":"以价值大小决定行棋次序，先走目数多、发展大或关乎全局的棋。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":6,"category":"十诀","order":6,"simplified":"逢危须弃","traditional":"逢危須棄","pinyin":"féng wēi xū qì","pinyin_plain":"feng wei xu qi","english":"When in danger, abandon.","explanation_zh":"算到无法挽救的棋就应立即放弃，越逃损失越大；弃是为了更好地得。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":7,"category":"十诀","order":7,"simplified":"慎勿轻速","traditional":"慎勿輕速","pinyin":"shèn wù qīng sù","pinyin_plain":"shen wu qing su","english":"Be cautious; do not rush.","explanation_zh":"落子要谨慎，计算周全、看清变化后再行棋，不可凭主观轻率出手。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":8,"category":"十诀","order":8,"simplified":"动须相应","traditional":"動須相應","pinyin":"dòng xū xiāng yìng","pinyin_plain":"dong xu xiang ying","english":"Every move must harmonize.","explanation_zh":"局部要与全局呼应：得周围子力接应，借全局力量作战。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":9,"category":"十诀","order":9,"simplified":"彼强自保","traditional":"彼強自保","pinyin":"bǐ qiáng zì bǎo","pinyin_plain":"bi qiang zi bao","english":"When the opponent is strong, protect yourself.","explanation_zh":"敌强我弱时先求安定做活，不在对方厚处无理挑战。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":10,"category":"十诀","order":10,"simplified":"势孤取和","traditional":"勢孤取和","pinyin":"shì gū qǔ hé","pinyin_plain":"shi gu qu he","english":"When outnumbered, seek peace.","explanation_zh":"势孤时以灵活转身、谋活求和为要，不挑起无把握的正面厮杀。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":11,"category":"新十诀","order":1,"simplified":"持重勿贪","traditional":"持重勿貪","pinyin":"chí zhòng wù tān","pinyin_plain":"chi zhong wu tan","english":"Be steady; do not be greedy.","explanation_zh":"行棋以稳重为先，不因贪图便宜而冒进。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":"《新围棋十诀》十句中五句与《围棋十诀》重复，此处只收新出的五句。"},{"id":12,"category":"新十诀","order":3,"simplified":"相机而攻","traditional":"相機而攻","pinyin":"xiàng jī ér gōng","pinyin_plain":"xiang ji er gong","english":"Attack according to the opportunity.","explanation_zh":"攻击要看时机与对象，不可为攻而攻。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":13,"category":"新十诀","order":4,"simplified":"扼要而据","traditional":"扼要而據","pinyin":"è yào ér jù","pinyin_plain":"e yao er ju","english":"Occupy the key points.","explanation_zh":"先占全局要点，据要而守，胜过四处落子。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":14,"category":"新十诀","order":5,"simplified":"弃子取势","traditional":"棄子取勢","pinyin":"qì zǐ qǔ shì","pinyin_plain":"qi zi qu shi","english":"Sacrifice stones for influence.","explanation_zh":"以弃子换取外势，把局部损失转化为全局主动。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":15,"category":"新十诀","order":10,"simplified":"先势后地","traditional":"先勢後地","pinyin":"xiān shì hòu dì","pinyin_plain":"xian shi hou di","english":"Influence before territory.","explanation_zh":"先经营外势与全局主动，再落实实地。","source":"zh.wikipedia 围棋十诀","source_url":"https://zh.wikipedia.org/wiki/%E5%9B%B4%E6%A3%8B%E5%8D%81%E8%AF%80","notes":""},{"id":16,"category":"布局","order":0,"simplified":"金角银边草肚皮","traditional":"金角銀邊草肚皮","pinyin":"jīn jiǎo yín biān cǎo dù pí","pinyin_plain":"jin jiao yin bian cao du pi","english":"Gold in the corners, silver on the sides, straw in the belly.","explanation_zh":"同样围十二目地，角上约需八子、边上十二子、中央十八子，故布局先角后边再中腹。","source":"zh.wikipedia 金角银边铜肚皮","source_url":"https://zh.wikipedia.org/wiki/%E9%87%91%E8%A7%92%E9%8A%80%E9%82%8A%E9%8A%85%E8%82%9A%E7%9A%AE","notes":"又作「金角银边铜肚皮」。"},{"id":17,"category":"布局","order":0,"simplified":"挂从宽处来","traditional":"掛從寬處來","pinyin":"guà cóng kuān chù lái","pinyin_plain":"gua cong kuan chu lai","english":"Approach from the wider side.","explanation_zh":"布局时宽处为大，挂角应从发展潜力大的一边着手。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":18,"category":"布局","order":0,"simplified":"立二拆三，立三拆四","traditional":"","pinyin":"lì èr chāi sān, lì sān chāi sì","pinyin_plain":"li er chai san, li san chai si","english":"With a wall of two, extend three; with a wall of three, extend four.","explanation_zh":"边上立起二子后可拆三，立起三子后可拆四，是取得根据地的拆边原则。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":"《棋经十三篇》作「立二可以拆三，立三可以拆四，与势子相望可以拆五」。"},{"id":19,"category":"布局","order":0,"simplified":"拆三拆四，分势关腹补为良","traditional":"拆三拆四，分勢關腹補為良","pinyin":"chāi sān chāi sì, fēn shì guān fù bǔ wèi liáng","pinyin_plain":"chai san chai si, fen shi guan fu bu wei liang","english":"A pressed three- or four-space extension is best reinforced toward the center.","explanation_zh":"拆三、拆四被对方两边逼住时，向中腹关补可兼顾中央与他处，避免被打入后以少战多。","source":"sohu 经典围棋口诀","source_url":"https://www.sohu.com/a/771171516_120390743","notes":""},{"id":20,"category":"布局","order":0,"simplified":"七子沿边活也输","traditional":"七子沿邊活也輸","pinyin":"qī zǐ yán biān huó yě shū","pinyin_plain":"qi zi yan bian huo ye shu","english":"Seven stones crawling along the edge: alive, yet losing.","explanation_zh":"布局阶段被压在三线、二线爬行七子，即使做活也失去外势，全局仍吃亏。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":21,"category":"布局","order":0,"simplified":"两番收腹成尤小","traditional":"兩番收腹成尤小","pinyin":"liǎng fān shōu fù chéng yóu xiǎo","pinyin_plain":"liang fan shou fu cheng you xiao","english":"A center territory squeezed from two sides is small.","explanation_zh":"围中腹时若被对方从两处挤压，实空要减去对方所得，价值往往不大。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":22,"category":"布局","order":0,"simplified":"高者在腹，下者在边，中者占角","traditional":"高者在腹，下者在邊，中者佔角","pinyin":"gāo zhě zài fù, xià zhě zài biān, zhōng zhě zhàn jiǎo","pinyin_plain":"gao zhe zai fu, xia zhe zai bian, zhong zhe zhan jiao","english":"The superior player plays the center, the middling player the corners, the inferior player the sides.","explanation_zh":"此谚从势力与全局立论：高手经营中腹，一般人守角，低手只知边线。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":"与重实地的「金角银边草肚皮」角度不同，并不矛盾。"},{"id":23,"category":"布局","order":0,"simplified":"棋从宽处拦","traditional":"棋從寬處攔","pinyin":"qí cóng kuān chù lán","pinyin_plain":"qi cong kuan chu lan","english":"Block from the wider side.","explanation_zh":"对方分投或点角时，应从自己发展潜力大、子力不重复的宽处拦住。","source":"sohu 18条围棋谚语详解","source_url":"https://www.sohu.com/a/367036919_120283986","notes":""},{"id":24,"category":"布局","order":0,"simplified":"入腹争正面","traditional":"入腹爭正面","pinyin":"rù fù zhēng zhèng miàn","pinyin_plain":"ru fu zheng zheng mian","english":"Entering the center, contend for the broad front.","explanation_zh":"双方进入中腹时，要抢先占据宽广的正面，迫使对方走小路。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":25,"category":"布局","order":0,"simplified":"逼孤多占地一二","traditional":"逼孤多佔地一二","pinyin":"bī gū duō zhàn dì yī èr","pinyin_plain":"bi gu duo zhan di yi er","english":"When pressing a lone group, take an extra point or two on the side.","explanation_zh":"攻逼对方孤棋时，可顺势在边上多占一二路，因为对方自顾不暇、无力反击。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":26,"category":"布局","order":0,"simplified":"拆三利敌角犹虚","traditional":"拆三利敵角猶虛","pinyin":"chāi sān lì dí jiǎo yóu xū","pinyin_plain":"chai san li di jiao you xu","english":"A three-space extension is good while the opponent's corner is still open.","explanation_zh":"对方角地空虚时，拆三比拆二更积极；被打入也有回旋余地。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":27,"category":"布局","order":0,"simplified":"局定飞边地欲足","traditional":"局定飛邊地欲足","pinyin":"jú dìng fēi biān dì yù zú","pinyin_plain":"ju ding fei bian di yu zu","english":"Once the position is settled, fly to the side to fill out territory.","explanation_zh":"大局已定时，用「飞」及时侵入对方边角，可使自己的实空更充实。","source":"sohu 经典围棋口诀","source_url":"https://www.sohu.com/a/771171516_120390743","notes":""},{"id":28,"category":"布局","order":0,"simplified":"托二宜其边已固","traditional":"托二宜其邊已固","pinyin":"tuō èr yí qí biān yǐ gù","pinyin_plain":"tuo er yi qi bian yi gu","english":"The second-line attachment is good when the opponent's side is already solid.","explanation_zh":"对方边地已坚实，二路托可使其重复；若对方尚未完整，则不宜轻易使用。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":29,"category":"布局","order":0,"simplified":"并二腹中堪拆二","traditional":"並二腹中堪拆二","pinyin":"bìng èr fù zhōng kān chāi èr","pinyin_plain":"bing er fu zhong kan chai er","english":"Two stones side by side in the center may jump two spaces.","explanation_zh":"中腹并排两子出头时可用大跳加快步伐，但要防对方靠断。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":30,"category":"布局","order":0,"simplified":"初棋无劫","traditional":"初棋無劫","pinyin":"chū qí wú jié","pinyin_plain":"chu qi wu jie","english":"There is no ko in the opening.","explanation_zh":"开局子少、尚未纠缠，难找劫材；此时打劫，先提劫的一方占便宜。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":31,"category":"布局","order":0,"simplified":"中央开花三十目","traditional":"中央開花三十目","pinyin":"zhōng yāng kāi huā sān shí mù","pinyin_plain":"zhong yang kai hua san shi mu","english":"A ponnuki in the center is worth thirty points.","explanation_zh":"布局阶段中央提子威力巨大，盘面子越少，这朵「花」对今后的影响越大。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":32,"category":"布局","order":0,"simplified":"二一路上多妙着","traditional":"","pinyin":"èr yī lù shàng duō miào zhāo","pinyin_plain":"er yi lu shang duo miao zhao","english":"The 1-2 point holds many clever moves.","explanation_zh":"一路与二路交界处常藏妙手，死活与官子都不可忽视。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":"「着」读 zhāo，指一手棋。"},{"id":33,"category":"布局","order":0,"simplified":"遇劫先提","traditional":"","pinyin":"yù jié xiān tí","pinyin_plain":"yu jie xian ti","english":"In a ko, capture first.","explanation_zh":"打劫时先提劫可占先手之利，迫使对方先找劫材。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":""},{"id":34,"category":"布局","order":0,"simplified":"两扳长一气","traditional":"兩扳長一氣","pinyin":"liǎng bān cháng yí qì","pinyin_plain":"liang ban chang yi qi","english":"Two hanes gain one liberty.","explanation_zh":"连续两次扳可以多出一口气，对杀中常是生死之差。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":""},{"id":35,"category":"攻防","order":0,"simplified":"敌之要点即我之要点","traditional":"敵之要點即我之要點","pinyin":"dí zhī yào diǎn jí wǒ zhī yào diǎn","pinyin_plain":"di zhi yao dian ji wo zhi yao dian","english":"The opponent's key point is my key point.","explanation_zh":"对方形状的要点，往往也是我应先占的要点；这是寻找急所的捷径。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":36,"category":"攻防","order":0,"simplified":"攻击是最好的防御","traditional":"攻擊是最好的防禦","pinyin":"gōng jī shì zuì hǎo de fáng yù","pinyin_plain":"gong ji shi zui hao de fang yu","english":"Attack is the best defense.","explanation_zh":"对方侵入模样或企图先手得利时，主动攻击常比一味退让有效。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":37,"category":"攻防","order":0,"simplified":"攻紧宜宽，攻宽宜紧","traditional":"攻緊宜寬，攻寬宜緊","pinyin":"gōng jǐn yí kuān, gōng kuān yí jǐn","pinyin_plain":"gong jin yi kuan, gong kuan yi jin","english":"Attack tight stones loosely; attack loose stones tightly.","explanation_zh":"对有反弹力的孤棋宜宽攻制孤；对己方势力圈内未安定的棋则要严厉紧攻。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":38,"category":"攻防","order":0,"simplified":"逼敌近坚垒","traditional":"逼敵近堅壘","pinyin":"bī dí jìn jiān lěi","pinyin_plain":"bi di jin jian lei","english":"Drive the enemy toward your strong wall.","explanation_zh":"把对方棋子逼向自己厚实已活之处，才能最大限度发挥厚势威力。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":39,"category":"攻防","order":0,"simplified":"压强不压弱","traditional":"壓強不壓弱","pinyin":"yā qiáng bù yā ruò","pinyin_plain":"ya qiang bu ya ruo","english":"Press the strong, not the weak.","explanation_zh":"靠压作战时应压对方较强的一块，走强自己，再伺机攻击较弱的一块。","source":"sohu 18条围棋谚语详解","source_url":"https://www.sohu.com/a/367036919_120283986","notes":""},{"id":40,"category":"攻防","order":0,"simplified":"腾挪自靠始","traditional":"騰挪自靠始","pinyin":"téng nuó zì kào shǐ","pinyin_plain":"teng nuo zi kao shi","english":"Sabaki begins with an attachment.","explanation_zh":"敌强我弱处理孤子时，正面硬拼吃亏，靠碰借劲才能求得行棋步调。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":41,"category":"攻防","order":0,"simplified":"能曲则曲，可立则立","traditional":"能曲則曲，可立則立","pinyin":"néng qū zé qū, kě lì zé lì","pinyin_plain":"neng qu ze qu, ke li ze li","english":"Bend when you can bend; stand when you can stand.","explanation_zh":"利用残子要留有余味：曲可长气、立可收气，二者皆能多加利用。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":""},{"id":42,"category":"攻防","order":0,"simplified":"出头关胜长，挖断须预防","traditional":"出頭關勝長，挖斷須預防","pinyin":"chū tóu guān shèng cháng, wā duàn xū yù fáng","pinyin_plain":"chu tou guan sheng chang, wa duan xu yu fang","english":"To run out, the one-point jump beats the stretch; guard against the wedge cut.","explanation_zh":"向中央出头时「关」比「长」快，但必须防对方挖断。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":43,"category":"攻防","order":0,"simplified":"滚打包收俱谨防","traditional":"滾打包收俱謹防","pinyin":"gǔn dǎ bāo shōu jù jǐn fáng","pinyin_plain":"gun da bao shou ju jin fang","english":"Beware the squeeze-and-roll capture.","explanation_zh":"滚打包收是极严厉的连续手法，对局中要避免己方棋形被这样收紧。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":44,"category":"攻防","order":0,"simplified":"对付跨断，软扳硬冲","traditional":"對付跨斷，軟扳硬衝","pinyin":"duì fù kuà duàn, ruǎn bān yìng chōng","pinyin_plain":"dui fu kua duan, ruan ban ying chong","english":"Against a crosscut, hane softly or push through firmly.","explanation_zh":"正面作战不利时用软扳转身；无后顾之忧时用硬冲断取利。","source":"sohu 经典围棋口诀","source_url":"https://www.sohu.com/a/771171516_120390743","notes":""},{"id":45,"category":"攻防","order":0,"simplified":"棋从断处生","traditional":"棋從斷處生","pinyin":"qí cóng duàn chù shēng","pinyin_plain":"qi cong duan chu sheng","english":"Tactics are born where the cut is.","explanation_zh":"切开对方联络后，容易造成主动或乘势行棋的局面。","source":"sohu 18条围棋谚语详解","source_url":"https://www.sohu.com/a/367036919_120283986","notes":""},{"id":46,"category":"攻防","order":0,"simplified":"断哪边吃哪边","traditional":"斷哪邊吃哪邊","pinyin":"duàn nǎ biān chī nǎ biān","pinyin_plain":"duan na bian chi na bian","english":"Capture on the side you cut.","explanation_zh":"切断对方后，选择能吃住的那一边行棋，不要两边都想顾。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":47,"category":"攻防","order":0,"simplified":"扭断长一边","traditional":"扭斷長一邊","pinyin":"niǔ duàn cháng yì biān","pinyin_plain":"niu duan chang yi bian","english":"After a twist cut, extend on one side.","explanation_zh":"扭十字断开后，先长出一边稳住一块，再处理另一边。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":48,"category":"攻防","order":0,"simplified":"两处有情方可断","traditional":"兩處有情方可斷","pinyin":"liǎng chù yǒu qíng fāng kě duàn","pinyin_plain":"liang chu you qing fang ke duan","english":"Cut only when both sides have support.","explanation_zh":"断点两边都有己方接应时才可断，否则断了也吃不住。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":""},{"id":49,"category":"攻防","order":0,"simplified":"精华已尽多堪弃","traditional":"精華已盡多堪棄","pinyin":"jīng huá yǐ jìn duō kān qì","pinyin_plain":"jing hua yi jin duo kan qi","english":"Stones whose essence is spent may be sacrificed.","explanation_zh":"作用已尽、跑起来又累的棋子应果断弃掉，并尽量在用完之后再弃。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":50,"category":"攻防","order":0,"simplified":"取重舍轻方得胜","traditional":"取重捨輕方得勝","pinyin":"qǔ zhòng shè qīng fāng dé shèng","pinyin_plain":"qu zhong she qing fang de sheng","english":"Keep what matters, let go what does not, and you may win.","explanation_zh":"两块棋同时受攻时，救重要的一块、舍次要的一块，分清轻重才能取胜。","source":"sohu 18条围棋谚语详解","source_url":"https://www.sohu.com/a/367036919_120283986","notes":""},{"id":51,"category":"攻防","order":0,"simplified":"棋长一尺，无眼自活","traditional":"棋長一尺，無眼自活","pinyin":"qí cháng yì chǐ, wú yǎn zì huó","pinyin_plain":"qi chang yi chi, wu yan zi huo","english":"A group a foot long lives without eyes.","explanation_zh":"连成一长串的大龙很难被杀，不必担心做不出两眼。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":""},{"id":52,"category":"攻防","order":0,"simplified":"休贪小利除他病","traditional":"休貪小利除他病","pinyin":"xiū tān xiǎo lì chú tā bìng","pinyin_plain":"xiu tan xiao li chu ta bing","english":"Do not chase small gain and cure the opponent's defects.","explanation_zh":"贪小便宜下出随手棋，常帮对方补掉毛病，反而丧失机会。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":53,"category":"攻防","order":0,"simplified":"静能制动，劳输逸","traditional":"靜能制動，勞輸逸","pinyin":"jìng néng zhì dòng, láo shū yì","pinyin_plain":"jing neng zhi dong, lao shu yi","english":"Stillness controls motion; the tired loses to the rested.","explanation_zh":"安定的棋能控制不安定的棋；根据地与孤棋的有无决定劳逸。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":54,"category":"攻防","order":0,"simplified":"后先有变宜从紧","traditional":"後先有變宜從緊","pinyin":"hòu xiān yǒu biàn yí cóng jǐn","pinyin_plain":"hou xian you bian yi cong jin","english":"Where sente and gote may change, play tightly.","explanation_zh":"次序走错会形成完全不同的变化，故先后手可能逆转之处要从紧。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":55,"category":"攻防","order":0,"simplified":"彼此均先路必争","traditional":"彼此均先路必爭","pinyin":"bǐ cǐ jūn xiān lù bì zhēng","pinyin_plain":"bi ci jun xian lu bi zheng","english":"Contend for points that are sente for both.","explanation_zh":"对双方都是先手的要点（如压长、扳头）必须全力拼抢。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":56,"category":"攻防","order":0,"simplified":"三路之子送两个","traditional":"三路之子送兩個","pinyin":"sān lù zhī zǐ sòng liǎng gè","pinyin_plain":"san lu zhi zi song liang ge","english":"A third-line stone in atari: add a second and give both.","explanation_zh":"三线之子将被吃时再送一子，多延一口气加以利用，常能在外边打成外势。","source":"sohu 18条围棋谚语详解","source_url":"https://www.sohu.com/a/367036919_120283986","notes":""},{"id":57,"category":"死活","order":0,"simplified":"七死八活","traditional":"","pinyin":"qī sǐ bā huó","pinyin_plain":"qi si ba huo","english":"Seven on the second line die; eight live.","explanation_zh":"二路被包围的七子，对方先动手即死；长到八子则先动手也杀不死。","source":"sohu 18条围棋谚语详解","source_url":"https://www.sohu.com/a/367036919_120283986","notes":""},{"id":58,"category":"死活","order":0,"simplified":"角盘曲四，局终乃亡","traditional":"角盤曲四，局終乃亡","pinyin":"jiǎo pán qū sì, jú zhōng nǎi wáng","pinyin_plain":"jiao pan qu si, ju zhong nai wang","english":"Bent four in the corner dies at the end of the game.","explanation_zh":"角上曲四看似有眼，因劫材关系要到终局才死，不能算活。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":59,"category":"死活","order":0,"simplified":"大眼可赢小眼，斜行不如正行","traditional":"大眼可贏小眼，斜行不如正行","pinyin":"dà yǎn kě yíng xiǎo yǎn, xié xíng bù rú zhèng xíng","pinyin_plain":"da yan ke ying xiao yan, xie xing bu ru zheng xing","english":"A large eye beats a small eye; the diagonal is inferior to the straight.","explanation_zh":"对杀时大眼气长可胜小眼；补断取形则直行胜于斜行。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":60,"category":"死活","order":0,"simplified":"点方勿接","traditional":"點方勿接","pinyin":"diǎn fāng wù jiē","pinyin_plain":"dian fang wu jie","english":"Against the placement at the vital point, do not connect.","explanation_zh":"对方点入「方」形要点时，单粘往往中计，应另寻破眼或转身之法。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":"「点方」即点入「方」形要点，属破眼手筋。"},{"id":61,"category":"棋形与手筋","order":0,"simplified":"空三角愚型","traditional":"","pinyin":"kōng sān jiǎo yú xíng","pinyin_plain":"kong san jiao yu xing","english":"The empty triangle is a bad shape.","explanation_zh":"空三角子效低，是典型的愚形；行棋应避免走出这种凝形。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":62,"category":"棋形与手筋","order":0,"simplified":"矩形补断虎输飞","traditional":"矩形補斷虎輸飛","pinyin":"jǔ xíng bǔ duàn hǔ shū fēi","pinyin_plain":"ju xing bu duan hu shu fei","english":"To mend a rectangular cut, the knight's move beats the tiger's mouth.","explanation_zh":"曲尺形补断时用「飞」比「虎」好，飞不怕对方刺的利用。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":63,"category":"棋形与手筋","order":0,"simplified":"双单形见定靠单","traditional":"雙單形見定靠單","pinyin":"shuāng dān xíng jiàn dìng kào dān","pinyin_plain":"shuang dan xing jian ding kao dan","english":"Against a double-single shape, attach to the single stone.","explanation_zh":"对方并排两子加一跳时，靠住单子可把它走重成凝形，降低效率。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":"同页攻击格言又作「双单行见定敲单，乃令粘重」，疑为形/靠之讹。"},{"id":64,"category":"棋形与手筋","order":0,"simplified":"实尖虚镇","traditional":"實尖虛鎮","pinyin":"shí jiān xū zhèn","pinyin_plain":"shi jian xu zhen","english":"In solid positions, the diagonal; in open positions, the cap.","explanation_zh":"对方坚实处用尖攻取局部之利；空旷处用镇虚张声势、宽攻取势。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":65,"category":"棋形与手筋","order":0,"simplified":"棋拐一头大如牛","traditional":"棋拐一頭大如牛","pinyin":"qí guǎi yì tóu dà rú niú","pinyin_plain":"qi guai yi tou da ru niu","english":"A bend is as strong as an ox.","explanation_zh":"拐头能走厚自己并压迫对方，在中腹尤其有力。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":66,"category":"棋形与手筋","order":0,"simplified":"头软需扳，退虎任易长关","traditional":"頭軟需扳，退虎任易長關","pinyin":"tóu ruǎn xū bān, tuì hǔ rèn yì cháng guān","pinyin_plain":"tou ruan xu ban, tui hu ren yi chang guan","english":"Hane at a soft head; the defender may retreat, tiger, stretch or jump.","explanation_zh":"对方头软必须扳住；被扳一方可按情况选退、虎、长、关应对。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":67,"category":"棋形与手筋","order":0,"simplified":"两打同情不打，推敲扳虎兼长","traditional":"兩打同情不打，推敲扳虎兼長","pinyin":"liǎng dǎ tóng qíng bù dǎ, tuī qiāo bān hǔ jiān cháng","pinyin_plain":"liang da tong qing bu da, tui qiao ban hu jian chang","english":"With two ataris available, hold both; weigh hane, tiger and stretch.","explanation_zh":"有两种打吃可选时先保留变化，再按局面在扳、虎、长中取舍。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":68,"category":"棋形与手筋","order":0,"simplified":"逢方必点","traditional":"逢方必點","pinyin":"féng fāng bì diǎn","pinyin_plain":"feng fang bi dian","english":"Always place at the square shape's vital point.","explanation_zh":"对方走成「方」形时先点其要点，可破坏眼位与棋形。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":69,"category":"棋形与手筋","order":0,"simplified":"逢关无恶手","traditional":"逢關無惡手","pinyin":"féng guān wú è shǒu","pinyin_plain":"feng guan wu e shou","english":"The one-point jump is never a bad move.","explanation_zh":"「关」（一间跳）步伐畅、弹性好，通常不会是大恶手。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":""},{"id":70,"category":"棋形与手筋","order":0,"simplified":"扭十字长一方","traditional":"扭十字長一方","pinyin":"niǔ shí zì cháng yì fāng","pinyin_plain":"niu shi zi chang yi fang","english":"In a crosscut, extend on one side.","explanation_zh":"扭十字作战时先长出一边，避免两边同时被攻。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":""},{"id":71,"category":"棋形与手筋","order":0,"simplified":"追要飞，逃要跳","traditional":"追要飛，逃要跳","pinyin":"zhuī yào fēi, táo yào tiào","pinyin_plain":"zhui yao fei, tao yao tiao","english":"Chase with the knight's move; flee with the one-point jump.","explanation_zh":"追击用飞、逃跑用跳，是攻防中步调最好的常用手法。","source":"Sensei's Library 中文棋谚","source_url":"https://senseis.xmp.net/?ChineseGoProverbs","notes":""},{"id":72,"category":"棋形与手筋","order":0,"simplified":"左右同形走中间","traditional":"左右同形走中間","pinyin":"zuǒ yòu tóng xíng zǒu zhōng jiān","pinyin_plain":"zuo you tong xing zou zhong jian","english":"Play the center of symmetry.","explanation_zh":"左右或上下形状对称时，中间的对称点往往就是双方必争的要点。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":"又作「左右同形走中央」。"},{"id":73,"category":"棋形与手筋","order":0,"simplified":"势分入腹路皆公","traditional":"勢分入腹路皆公","pinyin":"shì fēn rù fù lù jiē gōng","pinyin_plain":"shi fen ru fu lu jie gong","english":"When influence is split, the center roads belong to both.","explanation_zh":"收官阶段中腹双方都有子力、又非必争之处时，轻易不要在中腹落子。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":74,"category":"棋形与手筋","order":0,"simplified":"二子头必扳","traditional":"二子頭必扳","pinyin":"èr zǐ tóu bì bān","pinyin_plain":"er zi tou bi ban","english":"Hane at the head of two stones.","explanation_zh":"对方两子紧贴时，应毫不犹豫扳住其头，宁可实地稍损也要控制大势。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":75,"category":"棋形与手筋","order":0,"simplified":"象眼尖穿忌两行，飞柔制劲","traditional":"象眼尖穿忌兩行，飛柔制勁","pinyin":"xiàng yǎn jiān chuān jì liǎng háng, fēi róu zhì jìn","pinyin_plain":"xiang yan jian chuan ji liang hang, fei rou zhi jin","english":"Against a peep through the elephant's eye, do not answer in line; a soft knight's move counters force.","explanation_zh":"对方穿象眼时不要贴着走，宜远一路以飞避其锋芒。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":76,"category":"棋形与手筋","order":0,"simplified":"马步镇逼常单跨，软扳硬冲","traditional":"馬步鎮逼常單跨，軟扳硬衝","pinyin":"mǎ bù zhèn bī cháng dān kuà, ruǎn bān yìng chōng","pinyin_plain":"ma bu zhen bi chang dan kua, ruan ban ying chong","english":"Against a knight's-move cap, a single crosscut is usual; then hane softly or push firmly.","explanation_zh":"对付马步镇逼，单跨最有力；对方跨后按情况软扳或硬冲。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":77,"category":"棋形与手筋","order":0,"simplified":"互关兼镇必关，任择飞尖与托","traditional":"互關兼鎮必關，任擇飛尖與托","pinyin":"hù guān jiān zhèn bì guān, rèn zé fēi jiān yǔ tuō","pinyin_plain":"hu guan jian zhen bi guan, ren ze fei jian yu tuo","english":"In mutual jumps and caps, the one behind must jump; choose fly, diagonal or attach.","explanation_zh":"双方争先出头时，落后一方要尽量走畅，可在飞、尖、托中择一。","source":"baike 围棋谚语","source_url":"https://baike.baidu.com/item/%E5%9B%B4%E6%A3%8B%E8%B0%9A%E8%AF%AD/4296393","notes":""},{"id":78,"category":"棋理","order":0,"simplified":"宁输数子，勿失一先","traditional":"寧輸數子，勿失一先","pinyin":"níng shū shù zǐ, wù shī yì xiān","pinyin_plain":"ning shu shu zi, wu shi yi xian","english":"Better to lose a few stones than to lose the initiative.","explanation_zh":"一先的价值常大于数子，不可因恋子而失先手。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":79,"category":"棋理","order":0,"simplified":"多算胜，少算不胜","traditional":"多算勝，少算不勝","pinyin":"duō suàn shèng, shǎo suàn bú shèng","pinyin_plain":"duo suan sheng, shao suan bu sheng","english":"More reading wins; less reading loses.","explanation_zh":"计算深者胜，计算浅者不胜，何况完全不算。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":80,"category":"棋理","order":0,"simplified":"弈者无同局","traditional":"弈者無同局","pinyin":"yì zhě wú tóng jú","pinyin_plain":"yi zhe wu tong ju","english":"No two games are the same.","explanation_zh":"千古无同局，每一盘都要因形制变，不可照搬定式。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":"又作「千古无同局」。"},{"id":81,"category":"棋理","order":0,"simplified":"善胜者不争，善阵者不战","traditional":"善勝者不爭，善陣者不戰","pinyin":"shàn shèng zhě bù zhēng, shàn zhèn zhě bú zhàn","pinyin_plain":"shan sheng zhe bu zheng, shan zhen zhe bu zhan","english":"The best victor does not fight; the best array does not battle.","explanation_zh":"以势屈人、不战而胜，是棋的上乘。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":82,"category":"棋理","order":0,"simplified":"与其恋子以求生，不若弃子而取势","traditional":"與其戀子以求生，不若棄子而取勢","pinyin":"yǔ qí liàn zǐ yǐ qiú shēng, bú ruò qì zǐ ér qǔ shì","pinyin_plain":"yu qi lian zi yi qiu sheng, bu ruo qi zi er qu shi","english":"Rather than cling to stones for life, sacrifice them for influence.","explanation_zh":"恋子求生常陷被动，弃子取势反能掌握全局。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":83,"category":"棋理","order":0,"simplified":"凡棋直行三则改，方聚四则非","traditional":"凡棋直行三則改，方聚四則非","pinyin":"fán qí zhí xíng sān zé gǎi, fāng jù sì zé fēi","pinyin_plain":"fan qi zhi xing san ze gai, fang ju si ze fei","english":"After three straight moves, change direction; a square four is wrong.","explanation_zh":"直线连行三子就应变化，聚成方四则成愚形。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":84,"category":"棋理","order":0,"simplified":"路虚而无眼，则先觑","traditional":"路虛而無眼，則先覷","pinyin":"lù xū ér wú yǎn, zé xiān qù","pinyin_plain":"lu xu er wu yan, ze xian qu","english":"Where the path is empty and there are no eyes, peep first.","explanation_zh":"对方联络空虚又无眼时，先觑一手探应，再决定后续手段。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":85,"category":"棋理","order":0,"simplified":"无害于他棋，则做劫","traditional":"無害於他棋，則做劫","pinyin":"wú hài yú tā qí, zé zuò jié","pinyin_plain":"wu hai yu ta qi, ze zuo jie","english":"If it harms no other stones, make a ko.","explanation_zh":"做劫不影响其他棋时，劫争可以成为主动的战术。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":86,"category":"棋理","order":0,"simplified":"择地而侵，无碍而进","traditional":"擇地而侵，無礙而進","pinyin":"zé dì ér qīn, wú ài ér jìn","pinyin_plain":"ze di er qin, wu ai er jin","english":"Invade where the ground invites; advance where nothing blocks.","explanation_zh":"侵消要选价值合适之处，推进要看有无阻碍，不可盲动。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":87,"category":"棋理","order":0,"simplified":"阔不可太疏，密不可太促","traditional":"闊不可太疏，密不可太促","pinyin":"kuò bù kě tài shū, mì bù kě tài cù","pinyin_plain":"kuo bu ke tai shu, mi bu ke tai cu","english":"Not too loose, not too tight.","explanation_zh":"行棋间距要适度：太疏易被分断，太促则子效低。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":88,"category":"棋理","order":0,"simplified":"彼众我寡，先谋其生","traditional":"彼眾我寡，先謀其生","pinyin":"bǐ zhòng wǒ guǎ, xiān móu qí shēng","pinyin_plain":"bi zhong wo gua, xian mou qi sheng","english":"When the opponent has more and I have less, first secure life.","explanation_zh":"敌众我寡时先求做活，再谈反击与取势。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":"原文下句为「我众彼寡，务张其势」。"},{"id":89,"category":"棋理","order":0,"simplified":"棋有不走之走，不下之下","traditional":"","pinyin":"qí yǒu bù zǒu zhī zǒu, bú xià zhī xià","pinyin_plain":"qi you bu zou zhi zou, bu xia zhi xia","english":"There are moves that consist in not playing.","explanation_zh":"该脱先时脱先、该不应时不应，本身就是一种高明的手段。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":90,"category":"棋理","order":0,"simplified":"误人者多方，成功者一路","traditional":"誤人者多方，成功者一路","pinyin":"wù rén zhě duō fāng, chéng gōng zhě yí lù","pinyin_plain":"wu ren zhe duo fang, cheng gong zhe yi lu","english":"Many ways lead astray; only one road leads to success.","explanation_zh":"歧路甚多，正着只有一条，需以计算与判断择定。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":91,"category":"棋理","order":0,"simplified":"两生勿断，皆活勿连","traditional":"兩生勿斷，皆活勿連","pinyin":"liǎng shēng wù duàn, jiē huó wù lián","pinyin_plain":"liang sheng wu duan, jie huo wu lian","english":"Do not cut two live groups; do not connect two live groups.","explanation_zh":"双方都活的棋不必强断，己方两块活棋也不必勉强连回。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":92,"category":"棋理","order":0,"simplified":"边不如角，角不如腹","traditional":"邊不如角，角不如腹","pinyin":"biān bù rú jiǎo, jiǎo bù rú fù","pinyin_plain":"bian bu ru jiao, jiao bu ru fu","english":"The side is not as good as the corner, nor the corner as the center.","explanation_zh":"此句从势力立论：边地最薄，角次之，中腹最能张势。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":"与重实地的「金角银边草肚皮」角度相反，合观方全。"},{"id":93,"category":"棋理","order":0,"simplified":"击左则视右，攻后则瞻前","traditional":"擊左則視右，攻後則瞻前","pinyin":"jī zuǒ zé shì yòu, gōng hòu zé zhān qián","pinyin_plain":"ji zuo ze shi you, gong hou ze zhan qian","english":"Strike left, but watch right; attack behind, but look ahead.","explanation_zh":"局部动手要兼顾全局，前后左右都需照应。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":94,"category":"棋理","order":0,"simplified":"与其无事而强行，不若因之而自补","traditional":"與其無事而強行，不若因之而自補","pinyin":"yǔ qí wú shì ér qiáng xíng, bú ruò yīn zhī ér zì bǔ","pinyin_plain":"yu qi wu shi er qiang xing, bu ruo yin zhi er zi bu","english":"Rather than force a move for no reason, reinforce according to the position.","explanation_zh":"无端强行动手不如顺势自补，补棋本身就是蓄力。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":95,"category":"棋理","order":0,"simplified":"善败者不乱","traditional":"善敗者不亂","pinyin":"shàn bài zhě bú luàn","pinyin_plain":"shan bai zhe bu luan","english":"One who is good at losing does not fall into disorder.","explanation_zh":"形势不利时仍能保持阵脚不乱，才有等待对方失误的机会。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":96,"category":"棋理","order":0,"simplified":"投棋勿逼，逼则使彼实而我虚","traditional":"投棋勿逼，逼則使彼實而我虛","pinyin":"tóu qí wù bī, bī zé shǐ bǐ shí ér wǒ xū","pinyin_plain":"tou qi wu bi, bi ze shi bi shi er wo xu","english":"Do not play too close; pressing makes the opponent solid and yourself empty.","explanation_zh":"过分逼近会使对方走实、自己走虚，反而易受攻击。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""},{"id":97,"category":"棋理","order":0,"simplified":"弱而不伏者愈屈，躁而求胜者多败","traditional":"弱而不伏者愈屈，躁而求勝者多敗","pinyin":"ruò ér bù fú zhě yù qū, zào ér qiú shèng zhě duō bài","pinyin_plain":"ruo er bu fu zhe yu qu, zao er qiu sheng zhe duo bai","english":"The weak who do not yield bend further; the hasty who seek victory often lose.","explanation_zh":"该忍时不忍会越陷越深；急躁求胜则多半招败。","source":"维基文库 棋经十三篇","source_url":"https://zh.wikisource.org/wiki/%E6%A3%8B%E7%B6%93","notes":""}]};
